import { Component, inject, OnInit, signal } from '@angular/core';
import { FormBuilder, FormGroup, Validators, FormArray, ReactiveFormsModule } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { TipoDocumentoMaestroService } from '../../../../../shared/services/tipo-documento-maestro.service';
import { SolicitudService, Municipio } from '../../../../../shared/services/solicitud.service';
import { TipoDocumentoMaestroPayload } from '../../../../../shared/models/tipo-documento-maestro.model';
import { extractErrorMessage } from '../../../../../shared/utils/error-utils';

@Component({
  selector: 'app-tipos-documento-form',
  imports: [ReactiveFormsModule],
  templateUrl: './tipos-documento-form.component.html',
})
export class TiposDocumentoFormComponent implements OnInit {
  private readonly fb = inject(FormBuilder);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly tipoDocumentoService = inject(TipoDocumentoMaestroService);
  private readonly solicitudService = inject(SolicitudService);
  protected readonly form: FormGroup;
  protected readonly isEdit = signal(false);
  protected readonly loading = signal(false);
  protected readonly saving = signal(false);
  protected readonly error = signal<string | null>(null);
  protected readonly municipios = signal<Municipio[]>([]);
  private id: number | null = null;

  constructor() {
    this.form = this.fb.group({
      nombre: ['', [Validators.required, Validators.maxLength(255)]],
      aliases: this.fb.array([]),
    });
  }

  get aliasesArray(): FormArray {
    return this.form.get('aliases') as FormArray;
  }

  ngOnInit(): void {
    this.loadMunicipios();
    this.route.paramMap.subscribe(params => {
      const idParam = params.get('id');
      if (idParam) {
        this.id = parseInt(idParam, 10);
        this.isEdit.set(true);
        this.loadTipoDocumento(this.id);
      }
    });
  }

  private loadMunicipios(): void {
    this.solicitudService.getMunicipios().subscribe({
      next: (m) => this.municipios.set(m),
      error: () => this.error.set('Error al cargar municipios.'),
    });
  }

  private loadTipoDocumento(id: number): void {
    this.loading.set(true);
    this.tipoDocumentoService.getById(id).subscribe({
      next: (data) => {
        this.form.patchValue({ nombre: data.nombre });
        if (data.aliases) {
          data.aliases.forEach(alias => {
            this.addAlias(alias.municipioId, alias.alias);
          });
        }
        this.loading.set(false);
      },
      error: (err) => {
        this.error.set(extractErrorMessage(err));
        this.loading.set(false);
      },
    });
  }

  protected addAlias(municipioId: number | '' = '', alias = ''): void {
    this.aliasesArray.push(
      this.fb.group({
        municipioId: [municipioId, Validators.required],
        alias: [alias, Validators.required],
      })
    );
  }

  protected removeAlias(index: number): void {
    this.aliasesArray.removeAt(index);
  }

  protected onSubmit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.saving.set(true);
    this.error.set(null);

    const payload: TipoDocumentoMaestroPayload = {
      nombre: this.form.value.nombre,
      aliases: this.form.value.aliases.map((a: { municipioId: string, alias: string }) => ({
        municipioId: parseInt(a.municipioId, 10),
        alias: a.alias,
      })),
    };

    const request$ = this.isEdit() && this.id
      ? this.tipoDocumentoService.update(this.id, payload)
      : this.tipoDocumentoService.create(payload);

    request$.subscribe({
      next: () => {
        this.saving.set(false);
        this.router.navigate(['/ejecutivos/configuracion/tipos-documento']);
      },
      error: (err) => {
        this.error.set(extractErrorMessage(err));
        this.saving.set(false);
      },
    });
  }

  protected onCancel(): void {
    this.router.navigate(['/ejecutivos/configuracion/tipos-documento']);
  }
}
